    }
    options = []
    for r in range(h - 1):
        for c in range(w - 1):
            for color, shape in patterns.items():
                cells = {(r + dr, c + dc) for dr, dc in shape}
                if cells <= occupied:
                    options.append((cells, color))
    by_cell = {cell: [] for cell in occupied}
    for option in options:
        for cell in option[0]:
            by_cell[cell].append(option)

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(o[0] <= remaining for o in by_cell[p]))
        for option in by_cell[cell]:
            cells, color = option
            if cells <= remaining:
                rest = cover(remaining - cells)
                if rest is not None:
                    return [(cells, color)] + rest
        return None

    tiles = cover(occupied)
    if tiles is None:
        raise ValueError("No tile decomposition found")
    output = [[0] * w for _ in range(h)]
    for cells, color in tiles:
        for r, c in cells:
            output[r][c] = color
    return output
